 const k=i*9,center=new THREE.Vector3((p[k]+p[k+3]+p[k+6])/3,(p[k+1]+p[k+4]+p[k+7])/3,(p[k+2]+p[k+5]+p[k+8])/3).project(camera);
 if(center.z < -1||center.z>1||Math.abs(center.x)>1||Math.abs(center.y)>1)continue;
