function cadImport(buffer,runtime={}){return cadImportClient.import(buffer,runtime);}
function inputBytes(bytes){
 const view=bytes instanceof ArrayBuffer?new Uint8Array(bytes):bytes instanceof Uint8Array?bytes:null;
 if(!view||!view.byteLength||view.byteLength>MAX_IMPORT_BYTES)throw Error('Import requires nonempty bytes (maximum 50 MB).');
 return view.slice();
}
function installInputProject(project,preserveUiSettings=false){
 // Both paths receive a fully validated new project before replacing visible state.
 // File UI keeps its existing discipline/category; new models clear conditions and properties.
 if(preserveUiSettings){setModel(project.meshes,project.name);sourceModel=project.sourceModel;updateDisciplineVisibility();}
 else api.loadProject(project);
 return api.exportProject();
}
async function readStepProject(bytes,options={},runtime={}){
 const original=inputBytes(bytes),settings=structuredClone(options);
 // Transfer a separate copy: the retained CAD source must never be detached.
 const result=await cadImport(original.slice().buffer,runtime);
 return createProjectFromStep({...settings,bytes:original,result,linearUnit:'millimeter'});
}
async function readStepUpdate(file){const project=await readStepProject(await file.arrayBuffer(),{name:file.name});return {name:project.name,meshes:project.meshes,sourceModel:project.sourceModel};}
$('model').onchange=async e=>{
 const file=e.target.files[0];if(!file)return;
 const revision=projectRevision,scaleToMm=Number($('unit').value);
 try{
  const snapshot=JSON.stringify(getProject());
  if(file.size>MAX_IMPORT_BYTES)throw Error('初期版の上限は50 MBです。');
  if(!/\.(step|stp|stl)$/i.test(file.name))throw Error('Supported model files: STEP, STP, STL.');
  $('model').disabled=true;status('モデルを読み込んでいます…');
  const bytes=inputBytes(await file.arrayBuffer()),stl=/\.stl$/i.test(file.name);
  const project=stl?createProjectFromStl({bytes,scaleToMm,name:file.name}):await readStepProject(bytes,{name:file.name});
  if(projectRevision!==revision||JSON.stringify(getProject())!==snapshot)throw Error('Inputs changed during import; import again');
  installInputProject(project,true);
  status(stl?'閉鎖した凸STLを読み込みました。面選択は三角形単位です。材料と条件を登録して体積メッシュ・解析を実行できます。':'STEP読み込み完了。CAD面またはブラシで領域を指定できます。');
 }catch(error){status('読み込み失敗: '+error.message);}finally{$('model').disabled=false;e.target.value='';cadUpdateUi?.refresh();}
};
