function compareRender(index,{field,deformScale,frameIndex,colorRange,camera:sharedCamera,internalComparison=false}){if(!$('cancel-run').disabled||visualExport.isActive()||comparisonRecording&&!internalComparison)throw Error('先に実行中の計算を中止してください。');const saved=typeof index==='number'?caseStore.at(index):null;if(typeof index==='number'&&!saved)throw Error('Unknown case');const output=saved?prepareCaseView(saved):index,selection=comparisonFrame(output.result,field,frameIndex),fieldInfo=resultFields(output.result).find(f=>f.id===field);
 const keep={analysis:lastAnalysis,range:resultColorRange,frame:acousticFrame,time:acousticDisplayTime,modal:modalIndex,field:$('result-field').value,scale:$('deform-scale').value};
 const savedCamera=camera.clone(),savedTarget=controls.target.clone(),savedDamping=controls.enableDamping;
 try{if(sharedCamera){controls.enableDamping=false;camera.position.fromArray(sharedCamera.position);camera.up.fromArray(sharedCamera.up);camera.fov=sharedCamera.fov;controls.target.fromArray(sharedCamera.target);camera.lookAt(controls.target);camera.updateProjectionMatrix();}lastAnalysis=output;resultColorRange=colorRange;acousticFrame=selection.frameIndex;acousticDisplayTime=null;modalIndex=0;$('result-field').value=field;$('deform-scale').value=deformScale;showAnalysis();renderer.render(scene,camera);
  const source=renderer.domElement,snapshot=document.createElement('canvas');snapshot.width=source.width;snapshot.height=source.height;snapshot.getContext('2d').drawImage(source,0,0);
  const selectedTemperature=output.result.kind==='thermal'&&field==='temperature',values=resultSliceContext.values;
  return {canvas:snapshot,min:selectedTemperature?Math.min(...values):resultSliceContext.min,max:selectedTemperature?Math.max(...values):resultSliceContext.max,unit:fieldInfo.unit,...selection};
 }finally{camera.copy(savedCamera);controls.target.copy(savedTarget);controls.enableDamping=savedDamping;camera.updateProjectionMatrix();lastAnalysis=keep.analysis;resultColorRange=keep.range;acousticFrame=keep.frame;acousticDisplayTime=keep.time;modalIndex=keep.modal;$('result-field').value=keep.field;$('deform-scale').value=keep.scale;
  if(keep.analysis)showAnalysis();else{analysisLayer.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});analysisLayer.clear();group.visible=true;markers.visible=true;$('result-legend').textContent='';resultSliceContext=null;}}}
