async function createExteriorDomain(paddingMm=Number($('fluid-padding').value),acoustic=false,creeping=false){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const original=api.exportProject(),source=(acoustic?exteriorAcousticSource:exteriorFluidSource)(original,paddingMm);api.loadProject({...original,sourceModel:source,study:acoustic?{...original.study,kind:'acoustic',modalAnalysis:false,acousticTransient:false,exteriorRadiation:true,directivityEnabled:false,sweep:false}:creeping?{kind:'creepingFlow',dynamicViscosity:Number($('flow-viscosity').value),fluidDensity:Number($('flow-density').value),stokesVelocityElement:$('stokes-element').value,freeStreamVelocity:['stokes-velocity-x','stokes-velocity-y','stokes-velocity-z'].map(id=>Number($(id).value)),...($('stokes-reference-length').value.trim()?{referenceLengthMm:Number($('stokes-reference-length').value)}:{})}:{kind:'fluidDomain'},conditions:[],selection:original.meshes.map(()=>[])});const revision=projectRevision;$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;try{const output=await guiAnalysis.run({operation:'mesh',options:{size:Number($('mesh-size').value),method:$('solver').value}});if(projectRevision!==revision)throw Error('Inputs changed during calculation; run again');const mesh=output.mesh,data={positions:mesh.surface.flatMap(f=>f.nodes.flatMap(i=>mesh.nodes.slice(3*i,3*i+3))),faceIds:mesh.surface.map(f=>f.faceTag),kind:'gmsh-surface',sourceHash:mesh.sourceHash};api.loadProject({...output.input,name:acoustic?(language==='en'?'Exterior acoustic domain':'外部音響領域'):(language==='en'?'Exterior fluid domain':'外部流体領域'),meshes:[data],selection:[[]],conditions:[]});lastAnalysis={...output,input:api.exportProject()};$('fluid-domain-info').textContent=(language==='en'?'Fluid volume: ':'流体体積: ')+mesh.summary.volumeMm3.toFixed(3)+' mm³';$('mesh-summary').textContent=mesh.summary.nodeCount+' 節点 / '+mesh.summary.elementCount+' 四面体';if(acoustic)status('外部音響領域を生成しました。断面表示で音源面を選び、音圧を指定してください。');else if(creeping)status('Stokes流の外部箱領域を生成しました。外側一様速度と物体の滑りなし境界を自動設定して解析します。');else status('外部流体領域を生成しました。断面表示で部品の空間を確認できます。');return lastAnalysis;}catch(e){if(projectRevision===revision)api.loadProject(original);throw e;}finally{$('mesh-run').disabled=false;$('solve-run').disabled=$('physics').value==='fluidDomain'||conditions.some(c=>c.cadUpdateRequired);$('cancel-run').disabled=true;}}
async function exteriorExample(){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const g=new THREE.BoxGeometry(10,10,10).toNonIndexed();g.translate(5,5,5);const d=geometryData(g);d.faceIds=d.faceIds.map((_,i)=>Math.floor(i/2));setModel([d],language==='en'?'Exterior domain reference':'外部流体領域の参照サンプル');g.dispose();sourceModel={kind:'box',bounds:[0,0,0,10,10,10]};$('mesh-size').value=6;return createExteriorDomain(10);}
$('exterior-create').onclick=()=>createExteriorDomain().catch(e=>status(e.message));$('exterior-demo').onclick=()=>exteriorExample().catch(e=>status(e.message));window.analysisApi.createExteriorDomain=createExteriorDomain;window.analysisApi.loadExteriorExample=exteriorExample;

