function appendComputeStatus(r){if(r.analysisAssessment){const a=r.analysisAssessment,p=document.createElement('p');p.dataset.provisional=String(a.provisional);p.textContent=a.provisional?(language==='en'?'Provisional analysis: explicit assumptions are included.':'暫定解析：明示した仮定を含みます。'):a.mode==='quantitative'?(language==='en'?'Input provenance confirmed.':'入力設定の根拠を確認済みです。'):(language==='en'?'Legacy input: full setup provenance is not recorded.':'従来入力：設定全体の根拠は未記録です。');$('result-summary').append(p);}fractureUi?.render(r.fracture);renderFatigueResult(r.fatigue);if(r.kind==='stokes')renderStokesResult(r);if(r.plasticity)renderPlasticity(r.plasticity);if(r.coupling){const c=r.coupling,p=document.createElement('p');p.textContent='振動→音 / '+c.sourceName+' / #'+(c.modeIndex+1)+' / 振幅 '+c.amplitudeMm+' mm / 位相 '+c.phaseDeg+'° / 法線速度 '+c.maxNormalVelocityMs.toPrecision(5)+' m/s / 音源パワー '+r.velocityInputPowerW.toPrecision(5)+' W';$('result-summary').append(p);}if(r.kind==='modal')renderModal(r);if(framesOf(r))renderTimeFrames(r);if(r.waveResolution){const w=r.waveResolution,p=document.createElement('p');p.textContent='波長 '+w.wavelengthMm.toPrecision(5)+' mm / 最長辺 '+w.maxEdgeMm.toPrecision(4)+' mm / 波長あたり '+w.pointsPerWavelength.toPrecision(4)+' 分割';$('result-summary').append(p);}if(r.radiation){const p=document.createElement('p');p.textContent='球面放射 / 半径 '+r.radiation.radiusMm.toPrecision(5)+' mm / 放射パワー '+r.radiation.powerW.toPrecision(5)+' W / 1次境界近似';$('result-summary').append(p);}if(r.farField)renderFarField(r.farField);if(r.hyperelastic){const h=r.hyperelastic,p=document.createElement('p');p.textContent='Neo-Hookean / Cauchy / Green-Lagrange / 荷重増分 '+h.loadSteps+' / Newton '+h.newtonIterations+' / 最小J '+h.minJ.toPrecision(6);$('result-summary').append(p);}if(r.materialEvaluation){const m=r.materialEvaluation,p=document.createElement('p');p.textContent='物性評価温度: '+m.temperatureMin.toFixed(3)+' → '+m.temperatureMax.toFixed(3)+' °C'+(m.interpolated?' / 補間ヤング率 '+(m.youngModulus/1e6).toPrecision(6)+' MPa / ポアソン比 '+m.poissonRatio.toPrecision(5):'');$('result-summary').append(p);}if(r.performance){const p=document.createElement('p');p.textContent='計算時間: '+r.performance.solveMs.toFixed(1)+' ms';$('result-summary').append(p);}if(r.native){const p=document.createElement('p');p.textContent='MFEM 4.10 / 倍精度 / 独立剛性組立 / 検証残差 '+r.native.verifiedResidual.toExponential(2);$('result-summary').append(p);}if(!r.gpu)return;const p=document.createElement('p');p.textContent=r.gpu.used?'WebGPU / '+r.gpu.adapter.description+(r.gpu.adapter.isFallbackAdapter===true?'（ソフトウェア代替）':'')+' / GPU '+r.gpu.gpuIterations+' 反復 / CPU補正 '+r.gpu.cpuCorrectionIterations+' / 検証残差 '+r.gpu.verifiedResidual.toExponential(2)+' / GPU処理 '+r.gpu.gpuPhaseMs.toFixed(1)+' ms / CPU補正 '+r.gpu.cpuCorrectionMs.toFixed(1)+' ms':'CPUへ切替: '+r.gpu.fallbackReason;$('result-summary').append(p);}

