window.fluidDomainApi=Object.freeze({isBusy:()=>fluidDomainOperations.isBusy(),async prepare(...args){const response=await fluidDomainOperations.prepare(...args);status(language==='en'?'Fluid domain prepared. Generate a volume mesh next.':'流体領域の入力を準備しました。体積メッシュを生成してください。');return response;},async applyMesh(...args){const response=await fluidDomainOperations.applyMesh(...args),summary=response.meshSummary;$('fluid-domain-info').textContent=(language==='en'?'Fluid volume: ':'流体体積: ')+summary.volumeMm3.toFixed(3)+' mm³';$('mesh-summary').textContent=summary.nodeCount+' nodes / '+summary.elementCount+' tetrahedra';status(language==='en'?'Fluid mesh applied. Select a physical model and explicitly configure its inputs to solve.':'流体メッシュを適用しました。解析する場合は分野と入力値を明示設定してください。');return response;}});
const caseSourceOperations=createCaseSourceOperations({studio:api,isBusy:()=>analysis.isBusy()||!!worker||!$('cancel-run').disabled||$('model').disabled||isVisualBusy(),getCase:({caseId,caseRevision},{guard})=>window.caseOperations.readSource({caseId,expectedRevision:caseRevision},{guard})});
window.caseSourceApi=Object.freeze({isBusy:()=>caseSourceOperations.isBusy(),async apply(...args){const response=await caseSourceOperations.apply(...args);status(language==='en'?'Saved case source applied. Review the physical setup before solving.':'保存ケースを連成源に設定しました。物理設定を確認してから解析してください。');return response;},async clear(...args){const response=await caseSourceOperations.clear(...args);status(language==='en'?'Saved case source cleared. Other physical settings are retained.':'保存ケースの連成源を解除しました。他の物理設定は保持しています。');return response;}});
window.builtinProjectApi=createBuiltinProjectOperations({studio:api,normalizeProject:project=>normalizeBrowserBuiltinProject(project,builtinInitialStudy),isBusy:()=>analysis.isBusy()||!$('cancel-run').disabled||$('model').disabled||isVisualBusy()});
window.cadUpdateApi=createCadUpdateOperations({studio:api,validateReplacement:validateBrowserCadReplacement,isBusy:()=>!$('cancel-run').disabled||$('model').disabled||isVisualBusy()});

