window.analysisApi.evaluateFracture=options=>fractureUi.evaluate(options);
window.resultAssessmentApi=createResultAssessmentApi({getAnalysis:()=>lastAnalysis,isBusy:()=>!$('cancel-run').disabled||$('model').disabled||isVisualBusy(),commit:next=>{
 const previous=lastAnalysis;lastAnalysis=next;
 try{renderFatigueResult(next.result.fatigue);fractureUi.render(next.result.fracture);showAnalysis();}
 catch(error){lastAnalysis=previous;try{renderFatigueResult(previous.result.fatigue);fractureUi.render(previous.result.fracture);showAnalysis();}catch(rollback){throw new AggregateError([error,rollback],'Assessment display and restoration failed');}throw error;}
 status(language==='en'?'Displayed result assessed.':'表示中の結果を評価しました。');
}});


window.printImportApi=installPrintImport({language:()=>language,translate:addTranslations,status,isBusy:()=>!$('cancel-run').disabled||$('model').disabled});

window.printOperations=createPrintOperations({...window.printImportApi,isBusy:()=>!$('cancel-run').disabled||$('model').disabled||$('print-file').disabled||isVisualBusy()});
window.printTransfer=createPrintTransfer({prints:window.printOperations});
installBrowserSession({studio:api,analysis,jobResults:createJobResultTransfer({analysis}),view:window.viewApi,resultView:window.resultViewApi,cases:window.caseOperations,comparisonViews:window.comparisonViewApi,exports:window.visualExportApi,namedViews:window.namedViewApi,caseArchives:window.caseArchiveTransfer,assessments:window.resultAssessmentApi,cadUpdates:window.cadUpdateApi,builtinProjects:window.builtinProjectApi,inputImports:window.inputImportTransfer,fluidDomains:window.fluidDomainApi,caseSources:window.caseSourceApi,prints:window.printOperations,printTransfers:window.printTransfer,caseBundles:window.caseBundleApi,caseBundleTransfers:window.caseBundleTransfer,measurements:window.measurementApi,getResult:()=>lastAnalysis,probe:(_mesh,_result,point,options)=>window.analysisApi.probe(point,options),isBusy:()=>!$('cancel-run').disabled||isVisualBusy()||$('model').disabled,translate:addTranslations,language:()=>language,showResult:(output,name)=>{if(!output.result)throw Error('A mesh-only job has no result case');const index=caseStore.count();window.caseApi.add(name,output);return viewCase(index);}});

installNativeFlowPanel({translate:addTranslations});
